import datetime,hashlib,json,pathlib
B=pathlib.Path(__file__).resolve().parent.parent;W=B.parents[2];OUT=B/'proof-sol-logs'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
prior=json.loads((B/'proof-sol-review-attempt2.json').read_text());doc=B/'PROOF-IMPLEMENTATION.md'
assert sha(doc)=='597a0e309e47359696581c1646a95be34343a00b6eb392c4fda84906679fc855'
expected='`proof.py`는 import 때 filesystem 변경을 하지 않는다. Linux, `/.dockerenv`, 명시적인 lab marker, `/proof/proof.py` 파일과 읽기 permission bit를 확인한 뒤에만 `/tmp/d12-proof`를 만들고 mode를 설정한다. read-only bind mount는 runner의 Docker 생성 옵션과 실행 전 inspect로 확인한다.'
assert expected in doc.read_text()
sourceMap={'D12-linux-terminal-basics.md':W/'docs/knowledge/D12-linux-terminal-basics.md','Dockerfile':B/'Dockerfile','proof.py':B/'source-proof/proof.py','run_proof.py':B/'source-proof/run_proof.py','source-manifest.json':B/'source-manifest.json'}
for name,path in sourceMap.items():assert sha(path)==prior['sourceSha256'][name],(name,path)
oldIndex=json.loads((OUT/'attempt2-original-attempt-index.json').read_text())
assert len(list((B/'proof-logs').glob('attempt-*.json')))==len(oldIndex)==18
for item in oldIndex:assert sha(B/'proof-logs'/item['file'])==item['sha256']
selPath=B/'selected-proof.json';sel=json.loads(selPath.read_text());assert sel['canonicalAttempt']=='docs/design/d12-2026-10-25/proof-logs/attempt-0665b1344c5b.json'
attempt=json.loads((W/sel['canonicalAttempt']).read_text());raw=json.loads((W/sel['linuxOutput']).read_text());assert raw==attempt['linuxActual'];assert (W/sel['linuxOutput']).read_text()==attempt['linuxFixtureOutput']['stdout']
assert sel['sourceSha256']=={'document':prior['sourceSha256']['D12-linux-terminal-basics.md'],'proof':prior['sourceSha256']['proof.py'],'runner':prior['sourceSha256']['run_proof.py']}
cases={x['case']:x['observations'] for x in raw['cases']}
values={'termPid':cases['signals']['pid'],'killPid':cases['signals']['kill_kill']['pid'],'loopbackPort':cases['network_readiness']['ephemeral_port'],'idlePid1':attempt['idleContainer']['pid1Comm']['stdout'].strip(),'idleExecPid':int(attempt['idleContainer']['execProcess']['stdout'].strip().split('=')[1])}
assert values==sel['imageValues'];assert values=={'termPid':40,'killPid':44,'loopbackPort':44397,'idlePid1':'sleep','idleExecPid':19}
assert sel['review']=='docs/design/d12-2026-10-25/proof-sol-review-attempt2.json' and sel['fullDocumentComplete'] is False
result={'schema':'d12-proof-sol-doc-addendum-v1','checkedAtUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'2차 검수 Q-M1 문장 정정과 기존 source/log fingerprint 보존 및 선택 proof 값만 검증. UI/이미지/전체 D12 완성 판정 아님.','verdict':'PASS','specVerdict':'PASS (2차 Linux 독립검수 결과 유지)','qualityVerdict':'PASS','counts':{'Critical':0,'Important':0,'Minor':0},'closedFinding':'Q-M1: proof.py guard의 파일/읽기비트 검사와 runner의 readonly bind 설정·inspect 확인을 정확히 분리','document':{'path':str(doc),'sha256':sha(doc),'verifiedSentence':expected},'sourceSha256':prior['sourceSha256'],'priorReview':str(B/'proof-sol-review-attempt2.json'),'priorReviewSha256':sha(B/'proof-sol-review-attempt2.json'),'sourceAndDockerfileUnchanged':True,'originalAttemptLogsUnchanged':{'count':18,'failed':15,'succeeded':3,'hashIndex':str(OUT/'attempt2-original-attempt-index.json'),'allHashesMatch':True},'selectedProof':{'actualPath':str(selPath),'requestedMainSelectedProofNameExists':False,'sha256':sha(selPath),'canonicalAttempt':sel['canonicalAttempt'],'linuxOutput':sel['linuxOutput'],'sourceSha256Matches':True,'rawOutputVerbatimMatches':True,'imageValues':values,'allValuesMatch':True,'currentReviewStatusMetadata':sel['reviewStatus'],'note':'selected-proof.json의 reviewStatus는 아직 이전 PASS_WITH_MINOR/pending 문구다. 보충 검수로 Q-M1은 종결됐으며 메인이 이 파일의 상태표시를 갱신할 수 있다. 이 리뷰는 해당 메타데이터를 수정하지 않았다.','fullDocumentComplete':False},'dockerRerunPerformed':False,'rerunNotNeededReason':'proof.py/run_proof.py/Dockerfile/manifest/18개 attempt가 2차 검수 fingerprint와 동일하고 변경은 보고문장1건이다.','protectedOrImplementationFilesEdited':False,'priorReportsPreserved':True,'limitationsPreserved':prior['limits']}
(B/'proof-sol-doc-addendum.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
md=['# D12 proof 문서 보충 검수','', '**PASS — Critical 0 / Important 0 / Minor 0.** 2차 검수 Q-M1을 종결했다. 기존 FAIL·2차 보고서는 보존했다.','', '문서는 proof.py의 파일·읽기 permission bit 검사와 runner의 read-only bind 설정·실행 전 inspect를 정확히 구분한다. 문서 SHA-256은 `'+sha(doc)+'`다.','', 'proof.py/run_proof.py/Dockerfile/source-manifest/원문 SHA는 2차 검수와 동일하다. 기존18개 attempt의 파일 해시도 모두 동일하다. Linux 재실행 없이 이전 독립 재현 결과를 유지한다.','', '실제 선택 파일은 '+str(selPath)+' 이다. canonical attempt0665b1344c5b, 원본 Linux JSON과 기록 stdout의 일치, 원문·proof·runner SHA 일치를 확인했다. TERM PID40, KILL PID44, loopback port44397, idle PID1 sleep, exec PID19도 선택값과 원출력이 일치한다.','', 'selected-proof.json의 reviewStatus는 이전 PASS_WITH_MINOR/pending 표현을 유지 중이다. 본 보충 검수로 해당 문장결함은 종결했으므로 메인이 상태표시를 갱신할 수 있다. 이 리뷰에서는 선택 파일을 수정하지 않았다. fullDocumentComplete=false의 전체 화면 작업 범위도 그대로다.','', '보충 보고: '+str(B/'proof-sol-doc-addendum.json'),'', '문서: '+str(doc),'', '기존2차 보고: '+str(B/'proof-sol-review-attempt2.json'),'', '이미지·UI·구현·보호문서·기존실행로그 수정이나 커밋은 하지 않았다.']
(B/'proof-sol-doc-addendum.md').write_text('\n'.join(md)+'\n')
print('PASS C0 I0 M0; source/Dockerfile/log18 unchanged; selected proof source+PID+port match; no Docker rerun')
